--
-- Table structure for table book
--

CREATE TABLE book (
  book_id int(11)   PRIMARY KEY AUTO_INCREMENT,
  book_name varchar(100) NOT NULL,
  book_description varchar(200) DEFAULT NULL,
  book_language varchar(50) DEFAULT NULL,
  total_pages int(11) DEFAULT NULL,
  release_year year(4) DEFAULT NULL,
  author_name varchar(50) DEFAULT NULL,
  book_cover mediumblob DEFAULT NULL,
  available_copies int(11) DEFAULT NULL CHECK (available_copies >= 0),
  FOREIGN KEY (author_name) REFERENCES author (author_name) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

