--
-- Table structure for table staff_member
--

CREATE TABLE staff_member (
  staff_id int(11) PRIMARY KEY AUTO_INCREMENT,
  member_name varchar(50) NOT NULL,
  username varchar(50) NOT NULL,
  password varchar(50) NOT NULL,
  email varchar(50) UNIQUE NOT NULL,
  age int(11) DEFAULT NULL CHECK (age>=25),
  salary decimal(8,2) DEFAULT NULL,
  position enum('Library Manager','Library Assistant','Library Technician','Librarian') DEFAULT NULL,
  hire_date date DEFAULT NULL,
  staff_status enum('Active','Inactive') DEFAULT 'Active',
  phone_num varchar(11) DEFAULT NULL,
  manager_id int(11) DEFAULT NULL,
   FOREIGN KEY (manager_id) REFERENCES staff_member (staff_id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

