--
-- Table structure for table borrowing_process
--

CREATE TABLE borrowing_process (
  process_code int(11) PRIMARY KEY AUTO_INCREMENT ,
  book_id int(11) DEFAULT NULL,
  user_id int(11) DEFAULT NULL,
  staff_id int(11) DEFAULT NULL,
  return_date date DEFAULT NULL,
  status enum('borrowed','returned','overdued') DEFAULT NULL,
  process_date date DEFAULT curdate(),
  due_date date DEFAULT NULL,
FOREIGN KEY (book_id) REFERENCES book (book_id) ON DELETE CASCADE ON UPDATE CASCADE,
FOREIGN KEY (user_id) REFERENCES users (User_id) ON DELETE CASCADE ON UPDATE CASCADE,
FOREIGN KEY (staff_id) REFERENCES staff_member (staff_id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

